class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # Dictionaries to store the maximum product for each alternating sum
        # even_len[s] = max product for even length subsequence with alternating sum s
        # odd_len[s] = max product for odd length subsequence with alternating sum s
        even_len = {}
        odd_len = {}

        for x in nums:
            # Create copies for the next state
            new_even = even_len.copy()
            new_odd = odd_len.copy()

            # Update from even_len: adding x will make the subsequence odd length
            for s, prod in even_len.items():
                ns = s + x
                np_val = prod * x
                if np_val <= limit:
                    # Update new_odd for ns
                    if ns not in new_odd or np_val > new_odd[ns]:
                        new_odd[ns] = np_val

            # Update from odd_len: adding x will make the subsequence even length
            for s, prod in odd_len.items():
                ns = s - x
                np_val = prod * x
                if np_val <= limit:
                    # Update new_even for ns
                    if ns not in new_even or np_val > new_even[ns]:
                        new_even[ns] = np_val

            # Start a new subsequence with x (length 1, odd)
            if x <= limit:
                if x not in new_odd or x > new_odd[x]:
                    new_odd[x] = x

            # Update the dictionaries
            even_len = new_even
            odd_len = new_odd

        # Check for k in both dictionaries
        res = -1
        if k in even_len:
            res = max(res, even_len[k])
        if k in odd_len:
            res = max(res, odd_len[k])

        return res

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        window_costs = [0] * (n - x + 1)
        for i in range(n - x + 1):
            window = nums[i:i+x]
            sorted_window = sorted(window)
            median = sorted_window[x // 2]
            cost = 0
            for num in window:
                cost += abs(num - median)
            window_costs[i] = cost

        INF = 10**18
        dp = [[INF] * (n + 1) for _ in range(k + 1)]

        for i in range(n + 1):
            dp[0][i] = 0

        for j in range(1, k + 1):
            for i in range(1, n + 1):
                if i >= x:
                    option1 = dp[j][i-1]
                    option2 = dp[j-1][i-x] + window_costs[i-x]
                    dp[j][i] = min(option1, option2)
                else:
                    dp[j][i] = dp[j][i-1]

        return dp[k][n]

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        P_num = [0] * (n + 1)
        P_cost = [0] * (n + 1)
        for i in range(1, n + 1):
            P_num[i] = P_num[i - 1] + nums[i - 1]
            P_cost[i] = P_cost[i - 1] + cost[i - 1]

        INF = float('inf')
        prev_dp = [INF] * (n + 1)
        prev_dp[0] = 0

        ans = INF

        for m in range(1, n + 1):
            curr_dp = [INF] * (n + 1)
            for i in range(m, n + 1):
                for j in range(m - 1, i):
                    if prev_dp[j] == INF:
                        continue
                    num_sum = P_num[i]
                    cost_sum = P_cost[i] - P_cost[j]
                    total_cost_here = (num_sum + m * k) * cost_sum
                    new_val = prev_dp[j] + total_cost_here
                    if new_val < curr_dp[i]:
                        curr_dp[i] = new_val
            if curr_dp[n] < ans:
                ans = curr_dp[n]
            prev_dp = curr_dp

        return ans

