    state = {node: 0 for node in nodes}
    cycles = 0
    for node in nodes:
        if state[node] != 0:
            continue
        stack = []
        current = node
        while current is not None and state.get(current, 0) == 0:
            state[current] = 1
            stack.append(current)
            # Get the next node
            next_node = mapping.get(current, None)
            # If next_node is not in the domain (i.e., not in nodes), then we stop.
            if next_node is not None and next_node not in nodes:
                next_node = None
            current = next_node
        if current is not None and state.get(current, 0) == 1:
            # We found a cycle.
            cycles += 1
        # Mark all nodes in the stack as visited.
        for node_in_stack in stack:
            state[node_in_stack] = 2

