class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_no_zero(n):
            if n <= 0:
                return 0
            s = str(n)
            n_len = len(s)
            from functools import lru_cache
            @lru_cache(maxsize=None)
            def dp(i, tight):
                if i == n_len:
                    return 1
                total = 0
                upper = int(s[i]) if tight else 9
                for d in range(1, upper + 1):
                    new_tight = tight and (d == upper)
                    total += dp(i + 1, new_tight)
                return total
            return dp(0, True)

        def count_no_zero_beautiful(n, s_val):
            if n <= 0 or s_val <= 0:
                return 0
            digits = list(map(int, str(n)))
            n_len = len(digits)
            if s_val > 9 * n_len:
                return 0
            from functools import lru_cache
            @lru_cache(maxsize=None)
            def dp(i, current_sum, rem, tight):
                if current_sum > s_val:
                    return 0
                if i == n_len:
                    return 1 if (current_sum == s_val and rem == 0) else 0
                total = 0
                upper = digits[i] if tight else 9
                for d in range(1, upper + 1):
                    new_tight = tight and (d == upper)
                    new_sum = current_sum + d
                    if new_sum > s_val:
                        break
                    new_rem = (rem * d) % s_val
                    total += dp(i + 1, new_sum, new_rem, new_tight)
                return total
            return dp(0, 0, 1, True)

        def count_up_to(n):
            if n <= 0:
                return 0
            total_no_zero = count_no_zero(n)
            beautiful_with_zero = n - total_no_zero
            max_sum = 9 * len(str(n))
            beautiful_no_zero = 0
            for s_val in range(1, max_sum + 1):
                beautiful_no_zero += count_no_zero_beautiful(n, s_val)
            return beautiful_with_zero + beautiful_no_zero

        return count_up_to(r) - count_up_to(l - 1)

