# Increase recursion depth just in case, but we'll use iterative segment tree if possible. 
# However, the recursive segment tree with lazy propagation is acceptable for 3e5.

class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size *= 2
        self.data = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

    def push(self, i):
        if self.lazy[i] != 0:
            for j in [2*i, 2*i+1]:
                if j < 2 * self.size:
                    self.data[j] += self.lazy[i]
                    self.lazy[j] += self.lazy[i]
            self.lazy[i] = 0

    def update_range(self, l, r, val, i=1, il=0, ir=None):
        if ir is None:
            ir = self.size - 1
        if r < il or ir < l:
            return
        if l <= il and ir <= r:
            self.data[i] += val
            self.lazy[i] += val
            return
        self.push(i)
        mid = (il + ir) // 2
        self.update_range(l, r, val, 2*i, il, mid)
        self.update_range(l, r, val, 2*i+1, mid+1, ir)
        self.data[i] = max(self.data[2*i], self.data[2*i+1])

    def update_point(self, i, val):
        # Get current value at i
        cur = self.query_point(i)
        diff = val - cur
        if diff != 0:
            self.update_range(i, i, diff)

    def query_point(self, i, idx=1, l=0, r=None):
        if r is None:
            r = self.size - 1
        if l == r:
            return self.data[idx]
        self.push(idx)
        mid = (l + r) // 2
        if i <= mid:
            return self.query_point(i, 2*idx, l, mid)
        else:
            return self.query_point(i, 2*idx+1, mid+1, r)

    def query_max(self, l, r, idx=1, il=0, ir=None):
        if ir is None:
            ir = self.size - 1
        if r < il or ir < l:
            return -10**18
        if l <= il and ir <= r:
            return self.data[idx]
        self.push(idx)
        mid = (il + ir) // 2
        left_max = self.query_max(l, r, 2*idx, il, mid)
        right_max = self.query_max(l, r, 2*idx+1, mid+1, ir)
        return max(left_max, right_max)

