    if not data:
        return
    n = int(data[0])
    A = list(map(int, data[1:1+n]))

    # Precompute L: L[i] = distinct count in A[0..i]
    L = [0] * n
    seen = set()
    for i in range(n):
        seen.add(A[i])
        L[i] = len(seen)

    # Precompute R: R[i] = distinct count in A[i..n-1]
    R = [0] * n
    seen = set()
    for i in range(n-1, -1, -1):
        seen.add(A[i])
        R[i] = len(seen)

    # If n<3, not possible by constraints, but constraints say n>=3.

    # Initialize segment tree
    seg_tree = SegmentTree(n)
    last_occ = [-1] * (n+1)  # since A_i in [1, n]

    ans = 0

    # Handle j=1 (0-indexed, so the second split is after index 1, meaning third part starts at 2)
    # i can only be 0.
    # V[0] = L[0] + 1
    seg_tree.update_point(0, L[0] + 1)
    F_1 = seg_tree.query_max(0, 0)
    # R[2] is the distinct count for the third part A[2..n-1]
    if n > 2:
        ans = max(ans, F_1 + R[2])
    else:
        # This case should not happen because n>=3, so j=1 implies n>=3, and R[2] exists.
        pass

    last_occ[A[1]] = 1

    # j from 2 to n-2 (0-indexed)
    for j in range(2, n-1):
        val = A[j]
        pos = last_occ[val]
        # Update existing i's: for i in [pos+1, j-2], add 1
        if pos + 1 <= j - 2:
            seg_tree.update_range(pos+1, j-2, 1)
        # Set V[j-1] = L[j-1] + 1
        seg_tree.update_point(j-1, L[j-1] + 1)
        # Query max in [0, j-1]
        F_j = seg_tree.query_max(0, j-1)
        candidate = F_j + R[j+1]
        if candidate > ans:
            ans = candidate
        last_occ[val] = j

    print(ans)

