class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        from collections import defaultdict, Counter

        min_b_at_a = [n] * (n + 1)
        pairs_by_a = defaultdict(list)

        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            pairs_by_a[a].append(b)

        min_b_val = [n] * (n + 1)
        next_min_b_val = [n] * (n + 1)
        count_min = [0] * (n + 1)

        for a in pairs_by_a:
            b_list = pairs_by_a[a]
            freq = Counter(b_list)
            sorted_b = sorted(freq.keys())
            min_b_val[a] = sorted_b[0]
            count_min[a] = freq[sorted_b[0]]
            if len(sorted_b) > 1:
                next_min_b_val[a] = sorted_b[1]
            else:
                next_min_b_val[a] = n
            min_b_at_a[a] = min_b_val[a] - 1

        M = [0] * (n + 2)
        M[n] = min_b_at_a[n]
        for i in range(n - 1, 0, -1):
            M[i] = min(min_b_at_a[i], M[i + 1])
        M[n + 1] = n

        S = [0] * (n + 2)
        S[n] = M[n] - n + 1
        for i in range(n - 1, 0, -1):
            S[i] = (M[i] - i + 1) + S[i + 1]
        S[n + 1] = 0

        max_valid = 0

        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a

            if b > min_b_val[a]:
                c_new = min_b_val[a] - 1
            else:
                if count_min[a] > 1:
                    c_new = min_b_val[a] - 1
                else:
                    if next_min_b_val[a] == n:
                        c_new = n
                    else:
                        c_new = next_min_b_val[a] - 1

            if c_new == min_b_at_a[a]:
                total_valid = S[1]
            else:
                M_new_arr = [0] * (a + 1)
                M_new_arr[a] = min(c_new, M[a + 1])
                current_sum_mid = M_new_arr[a] - a + 1
                if M_new_arr[a] == M[a]:
                    total_valid = S[1]
                else:
                    found_break = False
                    for l in range(a - 1, 0, -1):
                        M_new_arr[l] = min(min_b_at_a[l], M_new_arr[l + 1])
                        current_sum_mid += M_new_arr[l] - l + 1
                        if M_new_arr[l] == M[l]:
                            total_valid = (S[1] - S[l]) + current_sum_mid + S[a + 1]
                            found_break = True
                            break
                    if not found_break:
                        total_valid = current_sum_mid + S[a + 1]

            if total_valid > max_valid:
                max_valid = total_valid

        return max_valid

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1
        res = ['a'] * total_len
        fixed = [False] * total_len

        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos]:
                        if res[pos] != str2[j]:
                            return ""
                    else:
                        res[pos] = str2[j]
                        fixed[pos] = True

        for i in range(n):
            if str1[i] == 'F':
                start = i
                end = i + m
                if res[start:end] == list(str2):
                    j = end - 1
                    while j >= start:
                        if not fixed[j]:
                            res[j] = 'b'
                            break
                        j -= 1
                    if j < start:
                        return ""

        return "".join(res)

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        available = list(range(1, n + 1))
        rem_o = (n + 1) // 2
        rem_e = n // 2
        result = []

        for i in range(n):
            if i == 0:
                candidates = available[:]
            else:
                last_parity = result[-1] % 2
                required_parity = 1 - last_parity
                candidates = [x for x in available if x % 2 == required_parity]

            chosen = False
            for candidate in candidates:
                if candidate % 2 == 1:
                    ro_after = rem_o - 1
                    re_after = rem_e
                else:
                    ro_after = rem_o
                    re_after = rem_e - 1

                len_remaining = n - i - 1
                next_parity = 1 - (candidate % 2)
                if next_parity == 1:
                    num_odd = (len_remaining + 1) // 2
                else:
                    num_odd = len_remaining // 2
                num_even = len_remaining - num_odd

                if ro_after == num_odd and re_after == num_even:
                    count = fact[ro_after] * fact[re_after]
                else:
                    count = 0

                if k <= count:
                    result.append(candidate)
                    available.remove(candidate)
                    rem_o = ro_after
                    rem_e = re_after
                    chosen = True
                    break
                else:
                    k -= count

            if not chosen:
                return []

        return result

