class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_pos(x, y):
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:
                return 3 * side + (side - y)

        positions = []
        for x, y in points:
            positions.append(get_pos(x, y))
        positions.sort()
        n = len(positions)
        extended = positions + [p + 4 * side for p in positions]

        def feasible(d):
            if d == 0:
                return True
            m = len(extended)
            nxt = [0] * m
            j = 0
            for i in range(m):
                if j < i:
                    j = i
                while j < m and extended[j] - extended[i] < d:
                    j += 1
                nxt[i] = j

            for i in range(n):
                count = 1
                cur = i
                while count < k:
                    cur = nxt[cur]
                    if cur >= i + n:
                        break
                    count += 1
                if count >= k:
                    return True
            return False

        low = 0
        high = 2 * side
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if feasible(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

