class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        n = len(target)
        # Precompute LCM for each mask
        lcm_cache = [1] * (1 << n)
        for mask in range(1, 1 << n):
            lcm_val = 1
            for i in range(n):
                if mask & (1 << i):
                    lcm_val = math.lcm(lcm_val, target[i])
            lcm_cache[mask] = lcm_val

        # Initialize min_cost for each mask to a large number
        min_cost = [float('inf')] * (1 << n)

        # For each number in nums, update min_cost for each mask
        for num in nums:
            for mask in range(1, 1 << n):
                lcm_val = lcm_cache[mask]
                # Calculate the cost to raise num to the next multiple of lcm_val
                remainder = num % lcm_val
                if remainder == 0:
                    cost = 0
                else:
                    cost = lcm_val - remainder
                if cost < min_cost[mask]:
                    min_cost[mask] = cost

        # DP to cover all targets
        dp = [float('inf')] * (1 << n)
        dp[0] = 0

        # Iterate over all masks from 1 to (1<<n)-1
        for mask in range(1, 1 << n):
            # Iterate over all non-empty submasks of mask
            sub = mask
            while sub > 0:
                # sub is a non-empty submask of mask
                # The rest of the mask is mask ^ sub
                if dp[mask ^ sub] != float('inf') and min_cost[sub] != float('inf'):
                    total = dp[mask ^ sub] + min_cost[sub]
                    if total < dp[mask]:
                        dp[mask] = total
                sub = (sub - 1) & mask

        return dp[(1 << n) - 1]

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        base = ord('a')
        freq = [[0] * 26 for _ in range(n + 1)]
        for i in range(1, n + 1):
            for c in range(26):
                freq[i][c] = freq[i-1][c]
            idx = ord(caption[i-1]) - base
            freq[i][idx] += 1

        INF = float('inf')
        dp = [(INF, None)] * (n + 1)
        dp[0] = (0, "")

        for i in range(1, n + 1):
            for L in range(3, i + 1):
                l = i - L
                r = i
                cum = 0
                median = 0
                for c in range(26):
                    count = freq[r][c] - freq[l][c]
                    cum += count
                    if cum >= (L + 1) // 2:
                        median = c
                        break

                candidates = []
                for dc in (-1, 0, 1):
                    c_val = median + dc
                    if 0 <= c_val <= 25:
                        candidates.append(c_val)
                candidates.sort()

                best_cost_block = INF
                best_c_block = None
                for c in candidates:
                    cost = 0
                    for k in range(26):
                        count = freq[r][k] - freq[l][k]
                        if count:
                            cost += count * abs(k - c)
                    if cost < best_cost_block or (cost == best_cost_block and c < best_c_block):
                        best_cost_block = cost
                        best_c_block = c

                total_cost = dp[l][0] + best_cost_block
                new_char = chr(best_c_block + base)
