    for j in range(M + 1):
        if j <= K:
            prev[j] = j
        else:
            prev[j] = INF

    # curr array, we will reuse it
    curr = [INF] * (M + 1)

    for i in range(1, N + 1):
        j_min = max(0, i - K)
        j_max = min(M, i + K)

        for j in range(j_min, j_max + 1):
            # Option 1: Deletion from S (or insertion into T)
            up = prev[j] + 1

            # Option 2: Insertion into S (or deletion from T)
            if j > 0:
                if j - 1 >= j_min:
                    left = curr[j-1] + 1
                else:
