class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Helper function to check if it's possible to have max substring length <= mid with numOps
        def can_achieve(mid):
            # If mid is 0, it's impossible (but mid will be at least 1)
            if mid == 0:
                return False
            flips = 0
            i = 0
            while i < n:
                j = i
                # Find the end of the current contiguous segment
                while j < n and s[j] == s[i]:
                    j += 1
                length = j - i
                # The number of flips needed for this segment is (length - 1) // mid
                flips += (length - 1) // mid
                i = j
                # Early termination if flips exceed numOps
                if flips > numOps:
                    return False
            return flips <= numOps

        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if can_achieve(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

