class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Separate numbers that are greater than threshold
        # Each such number forms its own component
        large_nums = [x for x in nums if x > threshold]
        count_large = len(large_nums)

        # Filter numbers that are <= threshold
        small_nums = [x for x in nums if x <= threshold]
        if not small_nums:
            return count_large

        # Create a set for fast lookup of small_nums
        num_set = set(small_nums)

        # Initialize DSU
        parent = {x: x for x in small_nums}
        rank = {x: 0 for x in small_nums}

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # For each number x in small_nums, iterate over multiples
        for x in small_nums:
            # Start from 2*x, then 3*x, etc., up to threshold
            multiple = 2 * x
            while multiple <= threshold:
                if multiple in num_set:
                    union(x, multiple)
                multiple += x

        # Count the number of unique roots in DSU for small_nums
        roots = set()
        for x in small_nums:
            roots.add(find(x))

        return len(roots) + count_large
